begin;

create temporary table question_seed (
  collection_slug text not null,
  slug text not null,
  title text not null,
  problem_statement text not null,
  difficulty text not null,
  topic_tags text[] not null,
  constraints jsonb not null,
  examples jsonb not null,
  starter_code_by_language jsonb not null,
  points integer not null
) on commit drop;

insert into question_seed
select * from jsonb_to_recordset($seed$
[{"collection_slug":"typescript-challenges","slug":"map-result-value","title":"Map a Result Value","problem_statement":"Define Result<T,E> as a success or failure discriminated union and implement mapResult. Apply transform only to a successful value, preserve the original error on failure, and infer Result<U,E> without casts or any. Do not catch exceptions thrown by transform.","difficulty":"Medium","topic_tags":["Generics","Discriminated Unions"],"constraints":["Input is a well-formed Result<T,E>","Transform is called exactly once only for success"],"examples":[{"input":"{ok:true,value:4}, n => `#${n}`","output":"{ok:true,value:\"#4\"}"},{"input":"{ok:false,error:{code:503}}, n => n * 2","output":"{ok:false,error:{code:503}}"}],"starter_code_by_language":{"TypeScript":"type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };\nfunction mapResult<T, E, U>(result: Result<T, E>, transform: (value: T) => U): Result<U, E> {\n  throw new Error(\"Implement mapResult\");\n}"},"points":150},{"collection_slug":"typescript-challenges","slug":"parse-user-payload-ts","title":"Validate an Unknown User Payload","problem_statement":"Implement parseUserPayload(input: unknown). Accept a non-array object with a non-empty string id, a string email containing exactly one @ and a dotted non-empty domain, and optional boolean active. Return {id,email,active}, defaulting active to true; reject invalid shapes with null and do not coerce.","difficulty":"Medium","topic_tags":["Unknown","Runtime Validation"],"constraints":["Input is untrusted unknown","Email validation is structural, not full RFC validation"],"examples":[{"input":"{\"id\":\"u7\",\"email\":\"ada@example.test\"}","output":"{\"id\":\"u7\",\"email\":\"ada@example.test\",\"active\":true}"},{"input":"{\"id\":\"u7\",\"email\":\"ada@example.test\",\"active\":\"yes\"}","output":"null"}],"starter_code_by_language":{"TypeScript":"interface UserPayload { id: string; email: string; active: boolean }\nfunction parseUserPayload(input: unknown): UserPayload | null {\n  throw new Error(\"Implement parseUserPayload\");\n}"},"points":150},{"collection_slug":"typescript-challenges","slug":"dispatch-typed-event","title":"Dispatch a Discriminated Event Safely","problem_statement":"Implement dispatchEvent for the AppEvent union and handler map below. Invoke exactly the handler matching event.type and return its result. Preserve the correlation between each event variant and its handler parameter using mapped types; do not use any or type assertions.","difficulty":"Hard","topic_tags":["Mapped Types","Discriminated Unions"],"constraints":["Every event variant has exactly one matching handler","Handlers may return a shared result type R"],"examples":[{"input":"dispatchEvent({type:\"created\",id:\"p4\"},{created:e=>e.id.length,removed:e=>e.permanent?e.id:\"\"})","output":"2"},{"input":"dispatchEvent({type:\"removed\",id:\"p4\",permanent:true},{created:e=>e.id.length,removed:e=>`${e.id}:${e.permanent}`})","output":"\"p4:true\""}],"starter_code_by_language":{"TypeScript":"type AppEvent = { type: \"created\"; id: string } | { type: \"removed\"; id: string; permanent: boolean };\ntype EventHandlers<R> = { [K in AppEvent[\"type\"]]: (event: Extract<AppEvent, { type: K }>) => R };\nfunction dispatchEvent<R>(event: AppEvent, handlers: EventHandlers<R>): R {\n  throw new Error(\"Implement dispatchEvent\");\n}"},"points":200},{"collection_slug":"typescript-challenges","slug":"tuple-endpoints","title":"Return the Endpoints of a Tuple","problem_statement":"Implement tupleEndpoints for a non-empty readonly tuple. Return its first and last elements as a pair while preserving each endpoint's exact inferred type, including a one-element tuple where both results have the same type.","difficulty":"Medium","topic_tags":["Tuples","Conditional Types"],"constraints":["Input is a non-empty readonly tuple","Do not mutate input or use type assertions"],"examples":[{"input":"tupleEndpoints([\"order-9\", 4, true] as const)","output":"[\"order-9\",true]"},{"input":"tupleEndpoints([17] as const)","output":"[17,17]"}],"starter_code_by_language":{"TypeScript":"type Last<T extends readonly unknown[]> = T extends readonly [...unknown[], infer L] ? L : never;\nfunction tupleEndpoints<const T extends readonly [unknown, ...unknown[]]>(items: T): [T[0], Last<T>] {\n  throw new Error(\"Implement tupleEndpoints\");\n}"},"points":150},{"collection_slug":"typescript-chosen-property-values","slug":"pluck-typed-property-values","title":"Pluck a Typed Property from Records","problem_statement":"Implement pluckProperty for a readonly array of objects. Restrict key to keyof the object type and return values whose element type is exactly T[K], including unions and optional-property undefined. Preserve order and do not mutate the source array.","difficulty":"Easy","topic_tags":["keyof","Indexed Access Types"],"constraints":["All entries have the same inferred object type T","No key outside keyof T is accepted"],"examples":[{"input":"pluckProperty([{id:3},{id:8}], \"id\")","output":"[3,8]"},{"input":"pluckProperty([{label:\"new\"},{label:\"sent\"}], \"label\")","output":"[\"new\",\"sent\"]"}],"starter_code_by_language":{"TypeScript":"function pluckProperty<T, K extends keyof T>(items: readonly T[], key: K): T[K][] {\n  throw new Error(\"Implement pluckProperty\");\n}"},"points":100},{"collection_slug":"typescript-config-key-read","slug":"read-config-by-valid-key","title":"Read Configuration by a Valid Key","problem_statement":"Implement readConfigValue so key is restricted to keyof Config and the return type is exactly Config[K]. The config contains numeric port, string serviceName, and boolean verbose fields; reading a key must not widen the result to a union or unknown.","difficulty":"Easy","topic_tags":["keyof","Indexed Access Types"],"constraints":["Only top-level properties are read","Config is not modified"],"examples":[{"input":"readConfigValue({port:8080,serviceName:\"catalog\",verbose:false}, \"port\")","output":"8080"},{"input":"readConfigValue({port:8080,serviceName:\"catalog\",verbose:false}, \"serviceName\")","output":"\"catalog\""}],"starter_code_by_language":{"TypeScript":"interface Config { port: number; serviceName: string; verbose: boolean }\nfunction readConfigValue<K extends keyof Config>(config: Config, key: K): Config[K] {\n  throw new Error(\"Implement readConfigValue\");\n}"},"points":100},{"collection_slug":"typescript-deep-readonly-config","slug":"deep-readonly-config","title":"Expose Configuration as Deep Readonly","problem_statement":"Define DeepReadonly<T> recursively so nested object properties and array elements are readonly while functions remain callable. Implement readonlyConfig as a type-only view of its input; do not clone, freeze, or otherwise change the runtime object.","difficulty":"Hard","topic_tags":["Conditional Types","Readonly"],"constraints":["Handle primitives, functions, arrays, and nested objects","Input identity is preserved"],"examples":[{"input":"readonlyConfig({server:{ports:[8080,8443]}})","output":"{\"server\":{\"ports\":[8080,8443]}}"},{"input":"readonlyConfig({onStart:()=>\"ready\"}).onStart()","output":"\"ready\""}],"starter_code_by_language":{"TypeScript":"type DeepReadonly<T> = T extends (...args: never[]) => unknown ? T : T extends readonly (infer U)[] ? readonly DeepReadonly<U>[] : T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T;\nfunction readonlyConfig<T>(value: T): DeepReadonly<T> {\n  throw new Error(\"Implement readonlyConfig\");\n}"},"points":200},{"collection_slug":"typescript-exhaustive-shape-label","slug":"format-shape-label-exhaustively","title":"Format Shape Labels Exhaustively","problem_statement":"Implement shapeLabel for the Shape discriminated union. Return circle:<radius> for a circle and rectangle:<width>x<height> for a rectangle. Use a never-based exhaustiveness check so adding a new shape variant becomes a compile-time error.","difficulty":"Medium","topic_tags":["never","Exhaustiveness"],"constraints":["Circle and rectangle dimensions are non-negative finite numbers","Do not add a generic fallback label"],"examples":[{"input":"shapeLabel({kind:\"circle\",radius:2})","output":"\"circle:2\""},{"input":"shapeLabel({kind:\"rectangle\",width:3,height:4})","output":"\"rectangle:3x4\""}],"starter_code_by_language":{"TypeScript":"type Shape = { kind: \"circle\"; radius: number } | { kind: \"rectangle\"; width: number; height: number };\nfunction assertNever(value: never): never { throw new Error(`Unexpected shape: ${value}`); }\nfunction shapeLabel(shape: Shape): string {\n  throw new Error(\"Implement exhaustive shapeLabel\");\n}"},"points":150},{"collection_slug":"typescript-iso-date-guard","slug":"guard-calendar-date-string","title":"Guard a Real Calendar Date String","problem_statement":"Implement isCalendarDate(value) as a type guard accepting exactly YYYY-MM-DD strings that represent real Gregorian dates. Validate month lengths and leap years rather than relying on a Date parser that silently rolls invalid dates forward.","difficulty":"Medium","topic_tags":["Type Guards","Date Validation"],"constraints":["Input type is unknown","Year has exactly four decimal digits"],"examples":[{"input":"isCalendarDate(\"2024-02-29\")","output":"true"},{"input":"isCalendarDate(\"2023-02-29\")","output":"false"}],"starter_code_by_language":{"TypeScript":"type CalendarDate = `${number}-${number}-${number}`;\nfunction isCalendarDate(value: unknown): value is CalendarDate {\n  throw new Error(\"Implement isCalendarDate\");\n}"},"points":150},{"collection_slug":"typescript-api-error-validation","slug":"parse-api-error-response","title":"Parse an API Error Response","problem_statement":"Implement parseApiError for untrusted unknown input. Accept only a non-array object whose status is an integer from 400 through 599, message is a non-empty string, and optional code is a string. Return a normalized ApiError or null without coercion.","difficulty":"Medium","topic_tags":["Unknown","API Validation"],"constraints":["Do not trust properties before runtime checks","Unknown extra properties are ignored"],"examples":[{"input":"{\"status\":404,\"message\":\"Record missing\",\"code\":\"NOT_FOUND\"}","output":"{\"status\":404,\"message\":\"Record missing\",\"code\":\"NOT_FOUND\"}"},{"input":"{\"status\":\"503\",\"message\":\"Unavailable\"}","output":"null"}],"starter_code_by_language":{"TypeScript":"interface ApiError { status: number; message: string; code?: string }\nfunction parseApiError(input: unknown): ApiError | null {\n  throw new Error(\"Implement parseApiError\");\n}"},"points":150},{"collection_slug":"typescript-non-empty-array","slug":"require-non-empty-array","title":"Guard a Non-Empty Array","problem_statement":"Implement isNonEmptyArray as a type guard for readonly arrays. Return true exactly when the array has at least one element, narrowing it to NonEmptyArray<T> so callers can safely read index zero without a non-null assertion. Do not mutate the input.","difficulty":"Easy","topic_tags":["Tuples","Runtime Validation"],"constraints":["Input may be empty","Do not mutate the array"],"examples":[{"input":"isNonEmptyArray([\"queued\",\"sent\"])","output":"true"},{"input":"isNonEmptyArray([])","output":"false"}],"starter_code_by_language":{"TypeScript":"type NonEmptyArray<T> = readonly [T, ...T[]];\nfunction isNonEmptyArray<T>(items: readonly T[]): items is NonEmptyArray<T> {\n  throw new Error(\"Implement isNonEmptyArray\");\n}"},"points":100},{"collection_slug":"typescript-merge-default-options","slug":"merge-required-options-with-defaults","title":"Merge Required Options with Defaults","problem_statement":"Implement mergeOptions for a Settings type with theme, pageSize, and compact. Accept Partial<Settings>, apply supplied values over defaults, and return a fully required Settings object. Undefined optional values count as omitted; preserve the exact Settings type.","difficulty":"Medium","topic_tags":["Partial","Generics"],"constraints":["Settings fields are primitive and required in the result","Do not mutate defaults or input"],"examples":[{"input":"mergeOptions({theme:\"light\",pageSize:20,compact:false},{theme:\"dark\"})","output":"{theme:\"dark\",pageSize:20,compact:false}"},{"input":"mergeOptions({theme:\"light\",pageSize:20,compact:false},{pageSize:undefined})","output":"{theme:\"light\",pageSize:20,compact:false}"}],"starter_code_by_language":{"TypeScript":"interface Settings { theme: \"light\" | \"dark\"; pageSize: number; compact: boolean }\nfunction mergeOptions(defaults: Settings, input: Partial<Settings>): Settings {\n  throw new Error(\"Implement mergeOptions\");\n}"},"points":150},{"collection_slug":"typescript-settings-patch","slug":"apply-settings-patch","title":"Apply a Typed Settings Patch","problem_statement":"Implement applySettingsPatch(current, patch) as a shallow immutable update. The patch is Partial<Settings>; keys omitted from patch retain current values, while supplied values replace them. Return Settings and leave the original object unchanged.","difficulty":"Easy","topic_tags":["Partial","Immutability"],"constraints":["Settings has theme, pageSize, and compact fields","Patch keys use their Settings value types"],"examples":[{"input":"current={theme:\"light\",pageSize:10,compact:false}, patch={pageSize:25}","output":"{theme:\"light\",pageSize:25,compact:false}"},{"input":"current={theme:\"dark\",pageSize:10,compact:true}, patch={}","output":"{theme:\"dark\",pageSize:10,compact:true}"}],"starter_code_by_language":{"TypeScript":"interface Settings { theme: \"light\" | \"dark\"; pageSize: number; compact: boolean }\nfunction applySettingsPatch(current: Settings, patch: Partial<Settings>): Settings {\n  throw new Error(\"Implement applySettingsPatch\");\n}"},"points":100},{"collection_slug":"typescript-safe-map-values","slug":"transform-readonly-map-values","title":"Transform Values in a Readonly Map","problem_statement":"Implement transformMapValues for a ReadonlyMap<K,V>. Invoke transform once per entry with its value and key, preserve key identity and insertion order, and return a new Map<K,U>. The source map must not be modified.","difficulty":"Easy","topic_tags":["Map","Generics"],"constraints":["Keys retain their original K type","Transform returns U"],"examples":[{"input":"transformMapValues(new Map([[\"a\",2],[\"b\",5]]),(value,key)=>`${key}:${value}`)","output":"Map([[\"a\",\"a:2\"],[\"b\",\"b:5\"]])"},{"input":"transformMapValues(new Map([[\"x\",\"ok\"]]),value=>value.length)","output":"Map([[\"x\",2]])"}],"starter_code_by_language":{"TypeScript":"function transformMapValues<K, V, U>(source: ReadonlyMap<K, V>, transform: (value: V, key: K) => U): Map<K, U> {\n  throw new Error(\"Implement transformMapValues\");\n}"},"points":100},{"collection_slug":"typescript-set-difference","slug":"preserve-set-difference-type","title":"Compute a Typed Set Difference","problem_statement":"Implement setDifference(left,right) returning values in left that are absent from right. Preserve left insertion order and element type, use native Set membership semantics, and do not mutate either ReadonlySet.","difficulty":"Easy","topic_tags":["Set","Generics"],"constraints":["Both sets contain the same inferred element type T","Return a mutable array of T"],"examples":[{"input":"setDifference(new Set([\"open\",\"held\",\"closed\"]), new Set([\"held\"]))","output":"[\"open\",\"closed\"]"},{"input":"setDifference(new Set([2,4]), new Set([2,4]))","output":"[]"}],"starter_code_by_language":{"TypeScript":"function setDifference<T>(left: ReadonlySet<T>, right: ReadonlySet<T>): T[] {\n  throw new Error(\"Implement setDifference\");\n}"},"points":100},{"collection_slug":"typescript-concurrent-map","slug":"map-promises-with-bounded-concurrency","title":"Map Promises with Bounded Concurrency","problem_statement":"Implement mapConcurrent(items,limit,mapper). Invoke an async mapper for every item with its index, keep no more than limit calls in flight, and resolve results in original item order. Reject for a non-positive integer limit or propagate the first mapper rejection; no input mutation.","difficulty":"Hard","topic_tags":["Async","Generics","Concurrency"],"constraints":["0 <= items.length <= 100000","limit is a positive integer"],"examples":[{"input":"items=[2,3,4], limit=2, mapper=async n => n*n","output":"[4,9,16]"},{"input":"items=[\"a\",\"b\"], limit=1, mapper=async (s,i) => `${i}:${s}`","output":"[\"0:a\",\"1:b\"]"}],"starter_code_by_language":{"TypeScript":"async function mapConcurrent<T, U>(items: readonly T[], limit: number, mapper: (item: T, index: number) => Promise<U>): Promise<U[]> {\n  throw new Error(\"Implement mapConcurrent\");\n}"},"points":200},{"collection_slug":"typescript-collect-settled","slug":"collect-promise-outcomes-as-result","title":"Collect Promise Outcomes as a Result Union","problem_statement":"Implement collectOutcomes for a readonly array of promises. Resolve to an ordered array where each success is {ok:true,value} and each rejection is {ok:false,error}; preserve the original rejection reason as unknown. The returned promise itself must not reject because of an input promise.","difficulty":"Medium","topic_tags":["Async","Discriminated Unions"],"constraints":["Preserve input order regardless of settlement order","An empty input resolves to an empty array"],"examples":[{"input":"[Promise.resolve(6), Promise.reject(\"offline\")]","output":"[{ok:true,value:6},{ok:false,error:\"offline\"}]"},{"input":"[Promise.reject({code:429})]","output":"[{ok:false,error:{code:429}}]"}],"starter_code_by_language":{"TypeScript":"type Outcome<T> = { ok: true; value: T } | { ok: false; error: unknown };\nasync function collectOutcomes<T>(promises: readonly Promise<T>[]): Promise<Outcome<T>[]> {\n  throw new Error(\"Implement collectOutcomes\");\n}"},"points":150},{"collection_slug":"typescript-typed-retry","slug":"retry-operation-by-error-policy","title":"Retry an Operation by Error Policy","problem_statement":"Implement retryOperation(operation,maxAttempts,shouldRetry). Call the async operation at most maxAttempts times; after rejection retry only if shouldRetry accepts that rejection. Resolve immediately on success and reject with the last error when exhausted or not retryable.","difficulty":"Hard","topic_tags":["Async","Generics","Retry Policy"],"constraints":["maxAttempts is an integer of at least one","No delay is required between attempts"],"examples":[{"input":"operation fails twice then returns \"ok\", maxAttempts=3, shouldRetry=()=>true","output":"resolves to \"ok\" after 3 calls"},{"input":"operation always rejects \"invalid\", maxAttempts=4, shouldRetry=()=>false","output":"rejects \"invalid\" after 1 call"}],"starter_code_by_language":{"TypeScript":"async function retryOperation<T, E>(operation: () => Promise<T>, maxAttempts: number, shouldRetry: (error: E) => boolean): Promise<T> {\n  throw new Error(\"Implement retryOperation\");\n}"},"points":200},{"collection_slug":"typescript-group-union-by-kind","slug":"group-discriminated-union-by-kind","title":"Group a Union by Its Discriminant","problem_statement":"Define Grouped<U> so each literal kind maps to an array of only the union members having that kind. Implement groupByKind for a readonly discriminated union array; retain original order inside each group and preserve each group's exact member type.","difficulty":"Hard","topic_tags":["Mapped Types","Extract"],"constraints":["Each union member has a distinct string literal kind","Do not mutate the input array"],"examples":[{"input":"[{kind:\"text\",value:\"hi\"},{kind:\"count\",value:2},{kind:\"text\",value:\"bye\"}]","output":"{text:[{kind:\"text\",value:\"hi\"},{kind:\"text\",value:\"bye\"}],count:[{kind:\"count\",value:2}]}"},{"input":"[{kind:\"flag\",value:true}]","output":"{flag:[{kind:\"flag\",value:true}]}"}],"starter_code_by_language":{"TypeScript":"type Grouped<U extends { kind: string }> = { [K in U[\"kind\"]]: Extract<U, { kind: K }>[] };\nfunction groupByKind<U extends { kind: string }>(items: readonly U[]): Grouped<U> {\n  throw new Error(\"Implement groupByKind\");\n}"},"points":200},{"collection_slug":"typescript-parse-query-options","slug":"parse-query-options-typed","title":"Parse and Validate Typed Query Options","problem_statement":"Implement parseQueryOptions for a string record. page must be a positive safe decimal integer when present and defaults to 1; enabled accepts only case-insensitive true or false and defaults to false; tags split on commas, trim, and omit empty entries. Return null if page or enabled is invalid.","difficulty":"Medium","topic_tags":["Parsing","API Types","Validation"],"constraints":["Unknown query keys are ignored","No partial numeric parsing or numeric coercion is allowed"],"examples":[{"input":"{page:\"3\",enabled:\"TRUE\",tags:\"new, sale,,gift\"}","output":"{page:3,enabled:true,tags:[\"new\",\"sale\",\"gift\"]}"},{"input":"{page:\"2x\",enabled:\"false\",tags:\"\"}","output":"null"}],"starter_code_by_language":{"TypeScript":"interface QueryOptions { page: number; enabled: boolean; tags: string[] }\nfunction parseQueryOptions(input: Readonly<Record<string, string>>): QueryOptions | null {\n  throw new Error(\"Implement parseQueryOptions\");\n}"},"points":150}]
$seed$::jsonb) as seed(
  collection_slug text, slug text, title text, problem_statement text, difficulty text,
  topic_tags text[], constraints jsonb, examples jsonb, starter_code_by_language jsonb, points integer
);

update question_seed
set collection_slug = 'typescript-challenges';

do $$
declare seed_count integer; distinct_count integer;
begin
  select count(*), count(distinct slug) into seed_count, distinct_count from question_seed;
  if seed_count <> 20 or distinct_count <> 20 then
    raise exception 'Expected exactly 20 unique TypeScript questions; got % records and % slugs', seed_count, distinct_count;
  end if;
  if exists (
    select 1 from question_seed
    where char_length(btrim(problem_statement)) < 100
       or jsonb_array_length(constraints) < 2 or jsonb_array_length(examples) < 2
       or jsonb_object_length(starter_code_by_language) <> 1
       or title ilike '%placeholder%' or problem_statement ilike '%placeholder%'
       or not (starter_code_by_language ?& array['TypeScript'])
       or starter_code_by_language->>'TypeScript' ilike '%TODO%'
       or starter_code_by_language->>'TypeScript' not like '%function %'
       or starter_code_by_language->>'TypeScript' ilike '%any%'
  ) then raise exception 'TypeScript question is incomplete or lacks a typed starter'; end if;
  if (select count(distinct title) from question_seed) <> 20
     or (select count(distinct problem_statement) from question_seed) <> 20 then
    raise exception 'TypeScript question titles and statements must be distinct';
  end if;
  if exists (
    select 1 from question_seed s
    where not exists (
      select 1 from jsonb_array_elements(s.examples) as x(item)
      where x.item->>'output' not in ('null','[]','{}','')
    )
  ) then raise exception 'Each TypeScript question needs a substantive example output'; end if;
  if exists (select 1 from question_seed
    where slug in ('type-narrowing','array-map','deep-clone','string-formatter','url-parser','group-words-by-length-ts','safe-integer-parser-ts')) then
    raise exception 'TypeScript seed overlaps an existing question slug';
  end if;
  if not exists (select 1 from public.coding_test_sets where slug='typescript-challenges') then
    raise exception 'Missing collection typescript-challenges';
  end if;
end $$;

with collection as (
  select id from public.coding_test_sets where slug='typescript-challenges'
), ordered_seed as (
  select s.*, coalesce((select max(q.question_order) from public.coding_questions q
    join collection c on c.id=q.collection_id),0) + row_number() over (order by s.slug) as question_order
  from question_seed s
)
insert into public.coding_questions (
  collection_id, slug, title, problem_statement, difficulty, topic_tags, constraints,
  examples, starter_code_by_language, points, publication_status, question_order
)
select c.id, s.slug, s.title, s.problem_statement, s.difficulty, s.topic_tags, s.constraints,
  s.examples, s.starter_code_by_language, s.points, 'published', s.question_order
from ordered_seed s cross join collection c
on conflict (collection_id, slug) do nothing;

insert into public.coding_test_cases (question_id, case_order, test_input, expected_output, visibility)
select q.id, e.ordinality::integer, e.item->>'input', e.item->>'output', 'visible'
from question_seed s
join public.coding_test_sets c on c.slug='typescript-challenges'
join public.coding_questions q on q.collection_id=c.id and q.slug=s.slug
cross join lateral jsonb_array_elements(s.examples) with ordinality as e(item, ordinality)
on conflict (question_id, case_order) do nothing;

commit;
